  cx.fillStyle = 'rgba(23,27,42,.45)'; cx.font = font(14,400,MONO); cx.fillText('CLASSIFIED ARCHIVE \xB7 \u7EDD\u5BC6\u6863\u6848', 90, 98);
  cx.fillStyle = 'rgba(255,255,255,.72)'; cx.fillRect(W-330, 58, 250, 64);
